#include <stdio.h>
#include <stdlib.h>

#define NUM_ITEMS 5

int stock[NUM_ITEMS];
int price[NUM_ITEMS];

int main(int argc, char *argv[]) {
    int i;
    for (i = 1; i < argc; i += 3) {
        char *op = argv[i];
        int item = atoi(argv[i + 1]);
        int qty = atoi(argv[i + 2]);

        if (item < 0 || item >= NUM_ITEMS) {
            printf("INVALID_SKU\n");
            continue;
        }

        if (op[0] == 'S') {
            if (stock[item] < qty) {
                printf("INSUFFICIENT_STOCK sku=%d\n", item);
            } else {
                stock[item] -= qty;
                int revenue = price[item] * qty;
                printf("SELL sku=%d qty=%d revenue+=%d\n", item, qty, revenue);
            }
        } else if (op[0] == 'R') {
            stock[item] += qty;
            printf("RESTOCK sku=%d qty=%d\n", item, qty);
        } else {
            printf("INVALID_OP\n");
        }
    }

    printf("FINAL stock=");
    for (i = 0; i < NUM_ITEMS; i++) {
        printf("%d", stock[i]);
        if (i < NUM_ITEMS - 1) {
            putchar(',');
        }
    }
    printf(" revenue=0\n");

    return 0;
}
